/**
 * Poll an async resource on an interval, pausing while the tab is hidden.
 *
 * This is the INTERIM realtime mechanism. The legacy switchboard is driven by a
 * push socket; a Horizon app cannot open or subscribe to that socket, so until
 * NetSapiens exposes the feed to apps (see README) the board refreshes by
 * polling `horizonContext.api`. Polling is deliberately conservative:
 *
 *   - it pauses on `document.hidden`, so a backgrounded tab spends no quota;
 *   - a `nudge()` is returned so a stream event (call-events / device /
 *     registration) can trigger an immediate refresh between ticks, which is how
 *     the few live signals an app DOES get shorten the polling lag;
 *   - overlapping ticks are suppressed (a slow response never stacks requests).
 *
 * The per-app proxy budget is 100 requests / 60s. Keep total poll frequency
 * across all resources well under that.
 */
import { useCallback, useEffect, useRef, useState } from 'react';

export interface PolledResource<T> {
  data: T | undefined;
  error: Error | undefined;
  loading: boolean;
  /** Seconds since the last successful load, or null before the first. */
  ageSeconds: number | null;
  /** Force an immediate refresh (e.g. from a stream event). */
  nudge: () => void;
}

export function usePolledResource<T>(
  loader: () => Promise<T>,
  intervalMs: number,
  deps: ReadonlyArray<unknown>,
): PolledResource<T> {
  const [data, setData] = useState<T | undefined>(undefined);
  const [error, setError] = useState<Error | undefined>(undefined);
  const [loading, setLoading] = useState<boolean>(true);
  const [lastOk, setLastOk] = useState<number | null>(null);
  const [ageSeconds, setAgeSeconds] = useState<number | null>(null);

  const inFlight = useRef(false);
  const loaderRef = useRef(loader);
  loaderRef.current = loader;

  const run = useCallback(async () => {
    if (inFlight.current) return;
    if (typeof document !== 'undefined' && document.hidden) return;
    inFlight.current = true;
    try {
      const next = await loaderRef.current();
      setData(next);
      setError(undefined);
      setLastOk(Date.now());
    } catch (e) {
      setError(e instanceof Error ? e : new Error(String(e)));
    } finally {
      setLoading(false);
      inFlight.current = false;
    }
  }, []);

  // Reset and reload whenever the dependency identity changes (e.g. the selected
  // domain). Kicks a tick as soon as the tab is visible again.
  useEffect(() => {
    setLoading(true);
    setData(undefined);
    void run();
    const timer = window.setInterval(() => void run(), intervalMs);
    const onVisible = () => {
      if (!document.hidden) void run();
    };
    document.addEventListener('visibilitychange', onVisible);
    return () => {
      window.clearInterval(timer);
      document.removeEventListener('visibilitychange', onVisible);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [run, intervalMs, ...deps]);

  // A lightweight "age" ticker so the UI can show freshness without re-polling.
  useEffect(() => {
    const t = window.setInterval(() => {
      setAgeSeconds(lastOk == null ? null : Math.floor((Date.now() - lastOk) / 1000));
    }, 1000);
    return () => window.clearInterval(t);
  }, [lastOk]);

  const nudge = useCallback(() => void run(), [run]);

  return { data, error, loading, ageSeconds, nudge };
}
