/**
 * Virtual Switchboard console - the app's single full-page route (/apps/switchboard).
 *
 * Renders an attendant view entirely from `horizonContext.ui` (no MUI in the
 * bundle, so it re-themes with the host light/dark toggle):
 *
 *   - a BLF roster of every extension in the domain, with presence + on-call,
 *   - an active-calls panel,
 *   - a live queue board,
 *   - a park column (when the domain has park orbits).
 *
 * Data comes from `horizonContext.api` (NetSapiens v2), refreshed by
 * `usePolledResource` and nudged by the relayed host streams. This is the
 * READ + POLL build: the write side (answer/hold/transfer/park) and the
 * push socket feed both need capabilities a Horizon app cannot hold today.
 * See README "What needs NetSapiens". Every panel states its own data source
 * on screen so nothing is passed off as more live than it is.
 */
import type * as React from 'react';
import { useCallback, useEffect, useMemo, useState } from 'react';
import type { ChartTone, HorizonUI } from '@netsapiens/horizon-sdk';
import { useHorizonContext } from '@netsapiens/horizon-sdk';

import type { ZoneMarkerProps } from '../App';
import type { LiveSignal } from '../services/liveSignals';
import type { NsActiveCall, QueueEntry, RosterEntry } from '../types';
import {
  fetchActiveCalls,
  fetchDomains,
  fetchQueues,
  fetchRoster,
} from '../api/switchboard';
import { usePolledResource } from '../hooks/usePolledResource';
import { LIVE_SIGNAL_EVENT } from '../services/liveSignals';

// Scopes allowed to look across domains (and therefore to see the domain
// picker). Everyone else is locked to their own domain, which for an Office
// Manager is exactly right.
const MULTI_DOMAIN_SCOPES = ['Super User', 'Reseller', 'Site Manager'];

/** Presence string -> the kit's semantic tone. Never a colour literal. */
function presenceTone(presence: string): string {
  switch (presence) {
    case 'open':
    case 'available':
      return 'success';
    case 'busy':
    case 'oncall':
    case 'on-call':
      return 'warning';
    case 'dnd':
    case 'donotdisturb':
      return 'error';
    case 'away':
    case 'idle':
      return 'default';
    default:
      return 'default';
  }
}

function callLabel(c: NsActiveCall): { from: string; to: string; state: string } {
  const from =
    c['orig-from-name'] || c['orig-user'] || String(c['orig-from-uri'] ?? '') || '?';
  const to = c['term-to-name'] || c['term-user'] || '?';
  const state = c['call-state'] || (c['time-answer'] ? 'connected' : 'ringing');
  return { from: String(from), to: String(to), state: String(state) };
}

function freshnessLabel(ageSeconds: number | null): string {
  if (ageSeconds == null) return 'loading';
  if (ageSeconds <= 2) return 'just now';
  if (ageSeconds < 60) return `${ageSeconds}s ago`;
  return `${Math.floor(ageSeconds / 60)}m ago`;
}

export default function SwitchboardPage({ ...marker }: ZoneMarkerProps) {
  const { api, ui, user } = useHorizonContext();
  const eventBus = useHorizonContext().eventBus;

  const canPickDomain = MULTI_DOMAIN_SCOPES.includes(user.scope ?? '');
  const [selectedDomain, setSelectedDomain] = useState<string>(user.domain);

  // Reseller/super-user domain list for the picker (skipped for locked scopes).
  const domainsRes = usePolledResource(
    useCallback(async () => {
      if (!api || !canPickDomain) return [];
      return fetchDomains(api);
    }, [api, canPickDomain]),
    5 * 60 * 1000, // domains change rarely; 5 min
    [canPickDomain],
  );

  const roster = usePolledResource<RosterEntry[]>(
    useCallback(
      () => (api ? fetchRoster(api, selectedDomain) : Promise.resolve([])),
      [api, selectedDomain],
    ),
    15000,
    [selectedDomain],
  );

  const queuesRes = usePolledResource(
    useCallback(
      () =>
        api
          ? fetchQueues(api, selectedDomain)
          : Promise.resolve({ queues: [], parks: [] }),
      [api, selectedDomain],
    ),
    8000,
    [selectedDomain],
  );

  const callsRes = usePolledResource<NsActiveCall[]>(
    useCallback(
      () => (api ? fetchActiveCalls(api, selectedDomain) : Promise.resolve([])),
      [api, selectedDomain],
    ),
    5000,
    [selectedDomain],
  );

  // Relayed host streams shorten the polling lag and prove the app is wired to
  // whatever live feed it is granted. On any signal, nudge the pollers and note
  // the time so the header can show the app is receiving events.
  const [lastSignalAt, setLastSignalAt] = useState<number | null>(null);
  useEffect(() => {
    if (!eventBus) return;
    const handler = (data: unknown) => {
      const sig = data as LiveSignal;
      setLastSignalAt(sig?.at ?? Date.now());
      roster.nudge();
      queuesRes.nudge();
      callsRes.nudge();
    };
    eventBus.on(LIVE_SIGNAL_EVENT, handler);
    // The bus has no off() in the typed surface; the app-lifetime subscription
    // in App.tsx owns teardown. A page remount re-registers a fresh handler.
    return () => {
      /* handler is idempotent; bus teardown is owned by the app */
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [eventBus]);

  const roster0 = useMemo(() => roster.data ?? [], [roster.data]);
  const registeredCount = roster0.filter((r) => r.registered).length;
  const onCallCount = roster0.filter((r) => r.onCall).length;
  const queues = queuesRes.data?.queues ?? [];
  const parks = queuesRes.data?.parks ?? [];
  const calls = callsRes.data ?? [];
  const waiting = queues.reduce((sum, q) => sum + q.waiting, 0);

  const PageTemplate = ui?.templates?.PageTemplate;
  const {
    Alert,
    Box,
    Card,
    CardContent,
    Chip,
    Divider,
    IconButton,
    Paper,
    Select,
    StatBlock,
    Stack,
    Typography,
  } = ui ?? {};

  // Defensive fallback if an older host hands us a partial kit.
  if (!PageTemplate || !Stack || !Paper || !Typography || !Box) {
    return (
      <div {...marker} style={{ padding: 24 }}>
        <h1>Virtual Switchboard</h1>
        <p>Domain: {selectedDomain}</p>
        <p>
          This host did not provide the UI kit this page needs. Registered extensions:{' '}
          {roster0.length}.
        </p>
      </div>
    );
  }

  const liveReceiving =
    lastSignalAt != null && Date.now() - lastSignalAt < 60000;

  const headerStatus = (
    <Stack direction="row" spacing={1} alignItems="center">
      {Chip ? (
        <Chip
          size="small"
          label={liveReceiving ? 'live events: on' : 'live events: idle'}
          color={liveReceiving ? 'success' : 'default'}
        />
      ) : null}
      {Chip ? (
        <Chip
          size="small"
          variant="outlined"
          label={`calls ${freshnessLabel(callsRes.ageSeconds)}`}
        />
      ) : null}
    </Stack>
  );

  const actions =
    canPickDomain && Select ? (
      <Select
        label="Domain"
        value={selectedDomain}
        onChange={(e: React.ChangeEvent<HTMLInputElement>) =>
          setSelectedDomain(e.target.value)
        }
        options={(domainsRes.data ?? []).map((d) => ({
          value: String(d.domain),
          label: d.description ? `${d.domain} - ${d.description}` : String(d.domain),
        }))}
        sx={{ minWidth: 240 }}
      />
    ) : undefined;

  const statTone = (n: number, warnAbove = 0): ChartTone =>
    n > warnAbove ? 'warning' : 'neutral';

  return (
    <PageTemplate
      {...marker}
      title="Virtual Switchboard"
      subtitle={selectedDomain}
      headerStatus={headerStatus}
      actions={actions}
    >
      <Stack spacing={3}>
        {/* Honest banner: what is live vs. what is pending platform support. */}
        {Alert ? (
          <Alert severity="info">
            Read-only console. The roster, queues and active calls refresh by
            polling the NetSapiens v2 API through the host proxy, nudged by the
            host event streams this app is granted. Call control
            (answer/hold/transfer/park) and the push call feed need NetSapiens to
            expose them to apps - tracked separately.
          </Alert>
        ) : null}

        {/* Summary tiles */}
        <Box
          sx={{
            display: 'grid',
            gridTemplateColumns: 'repeat(auto-fit, minmax(160px, 1fr))',
            gap: 2,
          }}
        >
          {StatBlock ? (
            <StatBlock value={registeredCount} caption="Extensions registered" tone="success" />
          ) : null}
          {StatBlock ? (
            <StatBlock value={onCallCount} caption="On a call" tone={statTone(onCallCount)} />
          ) : null}
          {StatBlock ? (
            <StatBlock value={waiting} caption="Calls waiting in queue" tone={statTone(waiting)} />
          ) : null}
          {StatBlock ? (
            <StatBlock value={queues.length + parks.length} caption="Queues and parks" />
          ) : null}
        </Box>

        {/* Two columns: roster (wide) + live panels */}
        <Box
          sx={{
            display: 'grid',
            gridTemplateColumns: { xs: '1fr', lg: '2fr 1fr' },
            gap: 3,
            alignItems: 'start',
          }}
        >
          {/* ---- BLF roster ---- */}
          <Paper sx={{ p: 2.5 }}>
            <Stack
              direction="row"
              spacing={2}
              alignItems="center"
              justifyContent="space-between"
              sx={{ mb: 2 }}
            >
              <Typography variant="h6">Extensions</Typography>
              <Stack direction="row" spacing={1} alignItems="center">
                <Typography variant="body2" color="text.secondary">
                  {roster.loading && roster0.length === 0
                    ? 'Loading...'
                    : `${roster0.length} total - updated ${freshnessLabel(roster.ageSeconds)}`}
                </Typography>
                {IconButton ? (
                  <IconButton
                    icon="mdi:refresh"
                    aria-label="Refresh roster now"
                    size="small"
                    onClick={() => roster.nudge()}
                  />
                ) : null}
              </Stack>
            </Stack>

            {roster.error && Alert ? (
              <Alert severity="warning" sx={{ mb: 2 }}>
                Could not read the roster for {selectedDomain}: {roster.error.message}
              </Alert>
            ) : null}

            <Box
              sx={{
                display: 'grid',
                gridTemplateColumns: 'repeat(auto-fill, minmax(190px, 1fr))',
                gap: 1.5,
              }}
            >
              {roster0.map((r) => (
                <RosterTile key={r.extension} entry={r} ui={ui} />
              ))}
              {roster0.length === 0 && !roster.loading ? (
                <Typography variant="body2" color="text.secondary">
                  No extensions returned for this domain.
                </Typography>
              ) : null}
            </Box>
          </Paper>

          {/* ---- Right column: active calls, queues, parks ---- */}
          <Stack spacing={3}>
            <Paper sx={{ p: 2.5 }}>
              <Typography variant="h6" sx={{ mb: 1.5 }}>
                Active calls
              </Typography>
              {calls.length === 0 ? (
                <Typography variant="body2" color="text.secondary">
                  No active calls right now.
                </Typography>
              ) : (
                <Stack spacing={1.5} divider={Divider ? <Divider /> : undefined}>
                  {calls.map((c, i) => {
                    const { from, to, state } = callLabel(c);
                    return (
                      <Stack
                        key={String(c['call-unique-id'] ?? c['call-id'] ?? i)}
                        direction="row"
                        spacing={1}
                        alignItems="center"
                        justifyContent="space-between"
                      >
                        <Box sx={{ minWidth: 0 }}>
                          <Typography variant="body2" noWrap>
                            {from} <span style={{ opacity: 0.6 }}>to</span> {to}
                          </Typography>
                        </Box>
                        {Chip ? (
                          <Chip
                            size="small"
                            label={state}
                            color={state === 'connected' ? 'success' : 'warning'}
                          />
                        ) : null}
                      </Stack>
                    );
                  })}
                </Stack>
              )}
            </Paper>

            <Paper sx={{ p: 2.5 }}>
              <Typography variant="h6" sx={{ mb: 1.5 }}>
                Queues
              </Typography>
              {queues.length === 0 ? (
                <Typography variant="body2" color="text.secondary">
                  No queues in this domain.
                </Typography>
              ) : (
                <Stack spacing={1.25}>
                  {queues.map((q) => (
                    <QueueRow key={q.id} q={q} ui={ui} />
                  ))}
                </Stack>
              )}
            </Paper>

            {parks.length > 0 ? (
              <Paper sx={{ p: 2.5 }}>
                <Typography variant="h6" sx={{ mb: 1.5 }}>
                  Parks
                </Typography>
                <Stack spacing={1.25}>
                  {parks.map((q) => (
                    <QueueRow key={q.id} q={q} ui={ui} isPark />
                  ))}
                </Stack>
              </Paper>
            ) : null}
          </Stack>
        </Box>

        {Card && CardContent ? (
          <Card>
            <CardContent>
              <Typography variant="body2" color="text.secondary">
                Signed in as {user.displayName} ({user.scope ?? 'user'}) on{' '}
                {user.domain}. Data proxied through the host with your session; no
                credentials reach this app.
              </Typography>
            </CardContent>
          </Card>
        ) : null}
      </Stack>
    </PageTemplate>
  );
}

/* ------------------------------------------------------------------ */
/* Small presentational pieces, each handed only the kit parts it uses. */
/* ------------------------------------------------------------------ */

function RosterTile({ entry, ui }: { entry: RosterEntry; ui?: HorizonUI }) {
  const { Paper, Stack, Typography, Chip, Avatar, Box } = ui ?? {};
  if (!Paper || !Stack || !Typography || !Box) return null;
  const tone = presenceTone(entry.presence);
  return (
    <Paper
      variant="outlined"
      sx={{ p: 1.5, opacity: entry.registered ? 1 : 0.55 }}
    >
      <Stack direction="row" spacing={1.25} alignItems="center">
        {Avatar ? (
          <Avatar sx={{ width: 34, height: 34, fontSize: 14 }}>
            {entry.name.slice(0, 2).toUpperCase()}
          </Avatar>
        ) : null}
        <Box sx={{ minWidth: 0, flex: 1 }}>
          <Typography variant="body2" noWrap title={entry.name}>
            {entry.name}
          </Typography>
          <Typography variant="caption" color="text.secondary">
            Ext {entry.extension}
          </Typography>
        </Box>
      </Stack>
      <Stack direction="row" spacing={0.75} alignItems="center" sx={{ mt: 1 }}>
        {Chip ? (
          <Chip size="small" label={entry.onCall ? 'on call' : entry.presence} color={tone} />
        ) : null}
        {!entry.registered && Chip ? (
          <Chip size="small" variant="outlined" label="unregistered" />
        ) : null}
      </Stack>
      {entry.statusMessage ? (
        <Typography
          variant="caption"
          color="text.secondary"
          sx={{ display: 'block', mt: 0.5 }}
          noWrap
          title={entry.statusMessage}
        >
          {entry.statusMessage}
        </Typography>
      ) : null}
    </Paper>
  );
}

function QueueRow({
  q,
  ui,
  isPark = false,
}: {
  q: QueueEntry;
  ui?: HorizonUI;
  isPark?: boolean;
}) {
  const { Stack, Typography, Chip, Box } = ui ?? {};
  if (!Stack || !Typography || !Box) return null;
  return (
    <Stack direction="row" spacing={1} alignItems="center" justifyContent="space-between">
      <Box sx={{ minWidth: 0 }}>
        <Typography variant="body2" noWrap>
          {q.name}
        </Typography>
        <Typography variant="caption" color="text.secondary">
          Ext {q.id}
          {!isPark ? ` - ${q.agentsAvailable}/${q.agentsTotal} agents avail` : ''}
        </Typography>
      </Box>
      {Chip ? (
        <Chip
          size="small"
          label={`${q.waiting} waiting`}
          color={q.waiting > 0 ? 'warning' : 'default'}
        />
      ) : null}
    </Stack>
  );
}
