/**
 * TeleVoIPs Virtual Switchboard - the federated entry point the Horizon host loads.
 *
 * Headless orchestrator (renders nothing itself). In one effect it:
 *   - registers ONE full-page route at /apps/switchboard, and
 *   - installs the relayed host streams as "live signals" for the page.
 *
 * /apps has no section floor, so the console is reachable by the receptionist
 * scopes that actually run a switchboard (Office Manager, Site Manager, and up),
 * not just admins. We deliberately do NOT set `requiredScopes`: the page is
 * read-only and self-scopes to the signed-in user's domain, and an Office
 * Manager must be able to open it. Tighten later if entitlement should gate it.
 */
import type { HorizonContext } from '@netsapiens/horizon-sdk';
import { useEffect, useMemo, useRef } from 'react';
import {
  HorizonContextProvider,
  useRemoteApp,
} from '@netsapiens/horizon-sdk';

import SwitchboardPage from './pages/SwitchboardPage';
import { installLiveSignals } from './services/liveSignals';

// Injected at build time by webpack DefinePlugin (see webpack.config.js). The
// SDK derives the kebab app id ('televoips-switchboard') from it.
declare const __MF_NAME__: string;

/**
 * Props the host passes to a registered route component. We don't use the demo's
 * test-id harness, so this is just a pass-through bag the page spreads onto its
 * root element.
 */
export type ZoneMarkerProps = Record<string, unknown>;

export default function App(horizonContext: HorizonContext) {
  const { sdk } = useRemoteApp(horizonContext, __MF_NAME__);

  // The host rebuilds `horizonContext` (including `ui`) on every color-mode
  // change. Keep the wrapper identity stable but always read the LATEST context,
  // so the page's `ui` follows the mode the user is actually looking at.
  const contextRef = useRef(horizonContext);
  contextRef.current = horizonContext;

  const SwitchboardWithContext = useMemo(
    () =>
      function SwitchboardWithContext(props: ZoneMarkerProps) {
        return (
          <HorizonContextProvider context={contextRef.current}>
            <SwitchboardPage {...props} />
          </HorizonContextProvider>
        );
      },
    [],
  );

  useEffect(() => {
    sdk
      .registerRoute({
        id: 'televoips-switchboard',
        parentPath: '/apps',
        path: 'switchboard',
        label: 'Virtual Switchboard',
        icon: 'mdi:phone-in-talk',
        component: SwitchboardWithContext,
      })
      .catch((error) =>
        console.error('[switchboard] Failed to register route:', error),
      );

    // Subscribe to whatever relayed streams the app is granted; each event
    // nudges the page's pollers. Falls back to pure polling if none are granted.
    const teardownSignals = installLiveSignals(sdk, horizonContext.eventBus);

    return () => {
      sdk.unregisterRoute('televoips-switchboard');
      teardownSignals();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [sdk]);

  return null;
}
