/**
 * Live-signal bridge.
 *
 * A Horizon app cannot subscribe to the domain call / agent / queue / contacts
 * feeds the legacy switchboard uses (those live on the :8001 socket, and the
 * app has no credential for it). What an app CAN receive is the small set of
 * host-relayed streams, gated per-app by a `<stream>:listen` capability:
 *
 *   call-events   - the signed-in user's OWN softphone call lifecycle
 *   device        - device state changes
 *   registration  - SIP registration state changes
 *   subscriber    - user/subscriber record changes
 *
 * None of these is the domain-wide board feed, but each is a hint that something
 * changed, so we use them to shorten polling lag: on any relayed event we
 * re-emit one normalized signal on the app's event bus, and the page nudges its
 * pollers immediately instead of waiting for the next tick. If a stream is not
 * granted, subscribing throws; we swallow it and fall back to pure polling.
 *
 * This is wired in App.tsx (which holds the sdk), not in the page, so the
 * subscriptions live for the app's lifetime and survive route re-renders.
 */
import type { RemoteAppSDK, StreamEvent } from '@netsapiens/horizon-sdk';

/** The one event-bus key the page listens on for a "something changed" nudge. */
export const LIVE_SIGNAL_EVENT = 'switchboard:live-signal';

export interface LiveSignal {
  /** Which relayed stream produced it. */
  stream: 'call-events' | 'device' | 'registration' | 'subscriber';
  /** The event's own `type`, when present. */
  type?: string;
  at: number;
}

type EventBus = { emit: (event: string, data?: unknown) => void };

/**
 * Subscribe to every relayed stream the app is allowed, re-emitting a
 * normalized {@link LiveSignal} on the bus. Returns a cleanup that unsubscribes
 * all of them. Safe to call once; each failed subscription is logged and
 * skipped so one denied stream never blocks the others.
 */
export function installLiveSignals(
  sdk: RemoteAppSDK,
  eventBus: EventBus,
): () => void {
  const cleanups: Array<() => void> = [];

  const emit = (stream: LiveSignal['stream'], type?: string) => {
    eventBus.emit(LIVE_SIGNAL_EVENT, { stream, type, at: Date.now() } satisfies LiveSignal);
  };

  // call-events is the typed specialization; use its dedicated method.
  try {
    const off = sdk.subscribeToCallEvents(
      ['call-started', 'call-answered', 'call-missed', 'call-ended'],
      (event) => emit('call-events', (event as { type?: string }).type),
    );
    cleanups.push(off);
  } catch (e) {
    console.warn('[switchboard] call-events stream unavailable:', e);
  }

  const genericStreams: Array<LiveSignal['stream']> = [
    'device',
    'registration',
    'subscriber',
  ];
  for (const stream of genericStreams) {
    try {
      const off = sdk.subscribeToStream(
        stream,
        // An empty event-type list means "any event on this stream".
        [],
        (event: StreamEvent) => emit(stream, event.type),
      );
      cleanups.push(off);
    } catch (e) {
      console.warn(`[switchboard] ${stream} stream unavailable:`, e);
    }
  }

  return () => {
    for (const off of cleanups) {
      try {
        off();
      } catch {
        /* best effort */
      }
    }
  };
}
