/**
 * Switchboard data access - every read goes through the SDK's authenticated
 * `horizonContext.api` proxy (NetSapiens v2). Credentials never reach this
 * remote app; the host injects auth, scopes the call to the signed-in user, and
 * audits it. Paths are relative to `/ns-api/v2`.
 *
 * Confirmed against live v46-lab responses:
 *   GET /domains/:domain/users                    -> roster (presence, on-call)
 *   GET /domains/:domain/callqueues               -> queues + parks (one object,
 *                                                    split by dispatch-type)
 *   GET /domains/:domain/agents                   -> agent availability
 *   GET /domains/:domain/calls                    -> active calls
 *   GET /domains                                  -> reseller domain picker
 *
 * What is NOT here, and why: the write side (answer / hold / transfer / park)
 * and the live socket feed. `horizonContext.api` exposes GET/POST/PUT/DELETE
 * only (no PATCH, which the NetSapiens call-control verbs use), and an app has
 * no way to open or subscribe to the :8001 socket the legacy switchboard uses.
 * So this build is READ + POLL. See README "What needs NetSapiens".
 */
import type { HorizonApiClient } from '@netsapiens/horizon-sdk';

import type {
  NsActiveCall,
  NsAgent,
  NsCallQueue,
  NsDomain,
  NsUser,
  QueueEntry,
  RosterEntry,
} from '../types';

function toInt(v: number | string | undefined | null): number {
  const n = typeof v === 'string' ? parseInt(v, 10) : (v ?? 0);
  return Number.isFinite(n) ? Number(n) : 0;
}

function fullName(u: NsUser): string {
  const name = `${u['name-first-name'] ?? ''} ${u['name-last-name'] ?? ''}`.trim();
  return name || u.user || '?';
}

/**
 * A park orbit is a callqueue whose dispatch type marks it as a park. NetSapiens
 * spells this a few ways across versions, so match on the substring rather than
 * an exact literal.
 */
function isPark(q: NsCallQueue): boolean {
  return /park/i.test(q['callqueue-dispatch-type'] ?? '');
}

/** Is this extension currently registered (reachable)? */
function isRegistered(u: NsUser): boolean {
  const s = (u.portal_status ?? '').toLowerCase();
  // Empty is treated as unknown-but-present; an explicit offline/unreg marker is
  // the only thing that reads as not registered.
  return !/offline|unreg|not/i.test(s);
}

/** The BLF roster for a domain. */
export async function fetchRoster(
  api: HorizonApiClient,
  domain: string,
): Promise<RosterEntry[]> {
  const users = await api.get<NsUser[]>(`/domains/${domain}/users`, {
    limit: 500,
  });
  return (users ?? [])
    .filter((u) => u.user)
    .map((u) => ({
      extension: String(u.user),
      name: fullName(u),
      presence: (u['user-presence-status'] ?? 'unknown').toLowerCase(),
      statusMessage: u['status-message'] ?? '',
      department: u.department ?? '',
      onCall: toInt(u['active-calls-total-current']) > 0,
      registered: isRegistered(u),
    }))
    .sort((a, b) => a.extension.localeCompare(b.extension, undefined, { numeric: true }));
}

/** Queues and parks in one call, split by dispatch type. */
export async function fetchQueues(
  api: HorizonApiClient,
  domain: string,
): Promise<{ queues: QueueEntry[]; parks: QueueEntry[] }> {
  const rows = await api.get<NsCallQueue[]>(`/domains/${domain}/callqueues`, {
    limit: 500,
  });
  const mapped = (rows ?? [])
    .filter((q) => q.callqueue)
    .map((q): QueueEntry & { _park: boolean } => ({
      id: String(q.callqueue),
      name: q.description || String(q.callqueue),
      isPark: isPark(q),
      _park: isPark(q),
      waiting: toInt(q['active-queued-calls-total-current']),
      agentsAvailable: toInt(q['callqueue-count-agents-available']),
      agentsTotal: toInt(q['callqueue-count-agents-total']),
      agentsLoggedIn: toInt(q.agent_loggedin_count),
    }))
    .sort((a, b) => a.id.localeCompare(b.id, undefined, { numeric: true }));
  return {
    queues: mapped.filter((q) => !q._park),
    parks: mapped.filter((q) => q._park),
  };
}

/** Active calls in a domain. */
export async function fetchActiveCalls(
  api: HorizonApiClient,
  domain: string,
): Promise<NsActiveCall[]> {
  const rows = await api.get<NsActiveCall[]>(`/domains/${domain}/calls`, {
    limit: 200,
  });
  return rows ?? [];
}

/** Agent availability across a domain (optional secondary view). */
export async function fetchAgents(
  api: HorizonApiClient,
  domain: string,
): Promise<NsAgent[]> {
  const rows = await api.get<NsAgent[]>(`/domains/${domain}/agents`, {
    limit: 500,
  });
  return rows ?? [];
}

/** Domains visible to a reseller/super-user, for the domain picker. */
export async function fetchDomains(api: HorizonApiClient): Promise<NsDomain[]> {
  const rows = await api.get<NsDomain[]>(`/domains`, {
    limit: 1000,
    fields: 'domain,description,reseller',
  });
  return (rows ?? [])
    .filter((d) => d.domain)
    .sort((a, b) => String(a.domain).localeCompare(String(b.domain)));
}
